2	//   "I want to keep track of my clients. Let me add a client with their name and email.
3	//    Show me all my clients in one list."
4	//
5	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's
6	// /__test__ endpoint). The one seedable domain is `clients`, honouring { id, name, email }.
7	import { test, expect } from '@playwright/test';
8	import { resetAndSeed } from '../support/seed';
9	
10	test.describe('Clients', () => {
11	  test('a link in the nav opens the clients list', async ({ page }) => {
12	    await resetAndSeed({ clients: [] });
13	
14	    await page.goto('/');
15	    // The shell is present and Home still shows its empty state (unchanged behaviour).
16	    await expect(page.getByTestId('app-root')).toBeVisible();
17	    await expect(page.getByTestId('app-nav')).toBeVisible();
18	    await expect(page.getByTestId('home-empty')).toBeVisible();
19	
20	    // Clients is reachable from the nav; following it lands on the clients page.
21	    const navClients = page.getByTestId('nav-clients');
22	    await expect(navClients).toBeVisible();
23	    await navClients.click();
24	
25	    await expect(page).toHaveURL(/\/clients$/);
26	    await expect(page.getByTestId('clients-page')).toBeVisible();
27	  });
28	
29	  test('with no clients the list shows an empty state', async ({ page }) => {
30	    await resetAndSeed({ clients: [] });
31	
32	    await page.goto('/clients');
33	
34	    await expect(page.getByTestId('clients-page')).toBeVisible();
35	    await expect(page.getByTestId('clients-empty')).toBeVisible();
36	    // Nothing is listed yet.
37	    await expect(page.locator('[data-testid^="client-row-"]')).toHaveCount(0);
38	  });
39	
40	  test('all seeded clients are shown in one list, each with name and email', async ({ page }) => {
